import numpy as np
from tqdm import tqdm
import matplotlib.pyplot as plt
import os
from matplotlib.animation import FuncAnimation, FFMpegWriter

# =======================================================
# KONSTANTE
# =======================================================

G = 1.0               # gravitacijska konstanta
dt = 0.0005           # časovni korak
t_end = 4.0           # trajanje simulacije
n_steps = int(t_end / dt)

# skupna masa dvozvezdja
M_tot = 60.0          # M☉


# =======================================================
# FUNKCIJE ZA POSTAVITEV SISTEMA
# =======================================================

def setup_binary(a, q):
    """
    Ustvari dvozvezdje s skupno maso 60 M☉.
    q = razmerje mas m1/(m1+m2)
    """
    m1 = q * M_tot
    m2 = (1 - q) * M_tot
    
    # položaji glede na COM
    r1 = a * m2 / (m1 + m2)
    r2 = a * m1 / (m1 + m2)

    pos1 = np.array([-r1, 0.0])
    pos2 = np.array([ r2, 0.0])

    omega = np.sqrt(G * (m1 + m2) / a**3)
    v1 = np.array([0.0, -omega * r1])
    v2 = np.array([0.0,  omega * r2])

    return np.array([m1, m2]), np.vstack([pos1, pos2]), np.vstack([v1, v2])


def setup_third_star(R0, v3, m3):
    pos3 = np.array([-R0, 0.0])    # b=0 → direktno v COM dvozvezdja
    vel3 = np.array([v3, 0.0])
    return m3, pos3, vel3


# =======================================================
# GRAVITACIJA
# =======================================================

def accelerations(positions, masses):
    N = len(masses)
    a = np.zeros_like(positions)
    for i in range(N):
        for j in range(N):
            if i == j: continue
            r = positions[j] - positions[i]
            d2 = r @ r + 1e-12
            d3 = d2 * np.sqrt(d2)
            a[i] += G * masses[j] * r / d3
    return a


# =======================================================
# DETEKCIJA KONČNEGA SISTEMA
# =======================================================

def binding_energy(m1, m2, r1, r2, v1, v2):
    r12 = np.linalg.norm(r2 - r1)
    v12 = np.linalg.norm(v2 - v1)
    mu = m1*m2/(m1+m2)
    return 0.5*mu*v12**2 - G*m1*m2/r12


def classify_configuration(masses, pos, vel):
    """
    Vrne:
      - kateri dve zvezdi sta vezani (če sta)
      - kdo je izstreljen
      - hitrost izstreljene zvezde
    """

    E12 = binding_energy(masses[0], masses[1], pos[0], pos[1], vel[0], vel[1])
    E13 = binding_energy(masses[0], masses[2], pos[0], pos[2], vel[0], vel[2])
    E23 = binding_energy(masses[1], masses[2], pos[1], pos[2], vel[1], vel[2])

    energies = np.array([E12, E13, E23])

    # če katerakoli dva tvorita dvozvezdje
    if np.any(energies < 0):
        idx = np.argmin(energies)
        if idx == 0:
            pair = (0,1); esc = 2
        elif idx == 1:
            pair = (0,2); esc = 1
        else:
            pair = (1,2); esc = 0

        v_esc = np.linalg.norm(vel[esc])
        return "vezano", pair, esc, v_esc

    # drugače razpad
    v_max = max(np.linalg.norm(vel[0]), np.linalg.norm(vel[1]), np.linalg.norm(vel[2]))
    return "razpad", None, None, v_max


# =======================================================
# GLAVNA 3-BODY SIMULACIJA
# =======================================================

def run_simulation(a, q, m3, v3, R0=200.0):

    # dvozvezdje
    masses_bin, pos_bin, vel_bin = setup_binary(a, q)
    # tretja zvezda
    m3, pos3, vel3 = setup_third_star(R0, v3, m3)

    masses = np.array([masses_bin[0], masses_bin[1], m3])
    pos = np.vstack([pos_bin, pos3])
    vel = np.vstack([vel_bin, vel3])

    # leapfrog start
    a0 = accelerations(pos, masses)
    vel_half = vel + 0.5 * dt * a0

    positions = np.zeros((n_steps, 3, 2))
    velocities = np.zeros((n_steps, 3, 2))
    positions[0] = pos
    velocities[0] = vel

    for i in range(1, n_steps):
        pos = positions[i-1] + vel_half * dt
        a_new = accelerations(pos, masses)
        vel_half = vel_half + a_new * dt

        positions[i] = pos
        velocities[i] = vel_half - 0.5 * dt * a_new   # real velocities

    # klasifikacija konfiguracije
    final = classify_configuration(masses, positions[-1], velocities[-1])
    return final, positions, velocities


final, pos, vel = run_simulation(a=0.3, q=0.5, m3=10.0, v3=200.0)



def heatmap_a_v3( Na=50, Nv=50):

    a_values = np.linspace(0.4115, 0.4145, Na)
    v_values = np.linspace(153.5, 156, Nv)

    speed_matrix = np.zeros((Na, Nv))

    print("\n=== Generiram heatmap za 4. primer ===\n")

    for i, a in enumerate(a_values):
        for j, v3 in enumerate(v_values):

            final, _, _ = run_simulation(
                a=a,
                q=0.5,          # lahko kasneje samplaš tudi q
                m3=10.0,        # lahko kasneje scan-aš tudi m3
                v3=v3
            )

            # final = ("vezano"/"razpad", pair, esc_index, v_escape)
            v_esc = final[3]

            speed_matrix[i, j] = v_esc

            print(f"a={a:.3f}, v3={v3:.1f}  ->  v_esc={v_esc:.1f}")

    # ======= RISANJE HEATMAP =======

    plt.figure(figsize=(10,7))
    plt.imshow(
        speed_matrix,
        origin='lower',
        extent=[v_values[0], v_values[-1],
                a_values[0], a_values[-1]],
        aspect='auto',
        cmap='plasma'
    )

    plt.colorbar(label="končna hitrost izstreljene zvezde v_esc")
    plt.xlabel("začetna hitrost tretje zvezde v₃")
    plt.ylabel("razdalja v dvozvezdju a")
    plt.title("Heatmap končne hitrosti izstreljene zvezde")

    os.makedirs("figs", exist_ok=True)
    fname = "figs/heatmap_a_vs_v3_detailed2.pdf"
    plt.savefig(fname, bbox_inches="tight")
    plt.show()
    plt.close()

    print(f"\nHeatmap shranjena v: {fname}")

    return speed_matrix, a_values, v_values


def plot_trajectory(positions, a, v3):
    plt.figure(figsize=(7, 7))
    
    # orbite posameznih teles
    colors = ["tab:blue", "tab:orange", "tab:green"]
    labels = ["zvezda 1", "zvezda 2", "tretja zvezda"]

    for i in range(3):
        x = positions[:, i, 0]
        y = positions[:, i, 1]
        plt.plot(x, y, color=colors[i], label=labels[i])
        plt.scatter(x[0], y[0], color=colors[i], s=20)

    plt.xlabel("x")
    plt.ylabel("y")
    plt.title(f"Prelet za a={a}, v3={v3}")
    plt.grid(True)

    # equal scaling
    allx = positions[:, :, 0].flatten()
    ally = positions[:, :, 1].flatten()
    m = min(allx.min(), ally.min())
    M = max(allx.max(), ally.max())
    pad = 0.05 * (M - m)
    plt.xlim(m - pad, M + pad)
    plt.ylim(m - pad, M + pad)
    plt.gca().set_aspect("equal", adjustable="box")

    os.makedirs("figs", exist_ok=True)
    fname = f"figs/prelet_a{a:.3f}_v3{v3:.1f}_zoom.pdf"
    plt.savefig(fname, bbox_inches="tight")
    plt.close()
    print(f"Statični graf shranjen v: {fname}")


# =======================================================
# ANIMACIJA PRELETA
# =======================================================

def animate_trajectory(positions, a, v3, step=1):

    fig, ax = plt.subplots(figsize=(7, 7))
    ax.set_xlabel("x")
    ax.set_ylabel("y")
    ax.set_title(f"Animacija preleta (a={a}, v3={v3})")
    ax.grid(True)

    # dynamic camera padding
    def update_limits(i):
        xs = positions[i, :, 0]
        ys = positions[i, :, 1]
        xmin, xmax = xs.min(), xs.max()
        ymin, ymax = ys.min(), ys.max()
        span = max(xmax - xmin, ymax - ymin)
        if span == 0: span = 1
        padding = span * 0.3
        cx = 0.5 * (xmin + xmax)
        cy = 0.5 * (ymin + ymax)
        ax.set_xlim(cx - span/2 - padding, cx + span/2 + padding)
        ax.set_ylim(cy - span/2 - padding, cy + span/2 + padding)

    colors = ["tab:blue", "tab:orange", "tab:green"]
    points = [ax.plot([], [], "o", color=colors[i])[0] for i in range(3)]

    def init():
        for p in points:
            p.set_data([], [])
        return points

    def update(frame):
        update_limits(frame)
        for i, p in enumerate(points):
            p.set_data(positions[frame, i, 0], positions[frame, i, 1])
        return points

    frames = range(0, len(positions), step)

    os.makedirs("figs", exist_ok=True)
    fname = f"figs/prelet_anim_a{a:.3f}_v3{v3:.1f}.mp4"

    writer = FFMpegWriter(fps=60)
    with writer.saving(fig, fname, dpi=150):
        for f in frames:
            update(f)
            writer.grab_frame()

    plt.close()
    print(f"Animacija shranjena v: {fname}")


def closest_approach(positions, dt):
    """
    Izračuna, kako blizu se vpadna zvezda (index 2) približa
    posameznima zvezdama v dvozvezdju (index 0 in 1).

    positions: array oblike (n_steps, 3, 2)
    dt: časovni korak
    """
    # razdalja med (0,2) in (1,2) v vseh časovnih korakih
    r02 = np.linalg.norm(positions[:, 0, :] - positions[:, 2, :], axis=1)
    r12 = np.linalg.norm(positions[:, 1, :] - positions[:, 2, :], axis=1)

    # minimumi in ustrezni časi
    i_min_02 = np.argmin(r02)
    i_min_12 = np.argmin(r12)

    d_min_02 = r02[i_min_02]
    d_min_12 = r12[i_min_12]

    t_min_02 = i_min_02 * dt
    t_min_12 = i_min_12 * dt

    # absolutno najbližji približek
    if d_min_02 < d_min_12:
        pair = (0, 2)
        d_min = d_min_02
        t_min = t_min_02
    else:
        pair = (1, 2)
        d_min = d_min_12
        t_min = t_min_12

    print("Najbližji približek zvezda1–vpadna (0–2):")
    print(f"  d_min = {d_min_02:.6f}, t = {t_min_02:.3f}")
    print("Najbližji približek zvezda2–vpadna (1–2):")
    print(f"  d_min = {d_min_12:.6f}, t = {t_min_12:.3f}")
    print()
    print(f"ABSOLUTNO NAJBLIŽJE: par {pair}, d_min = {d_min:.6f}, t = {t_min:.3f}")

    return (d_min_02, t_min_02), (d_min_12, t_min_12), (pair, d_min, t_min)

def find_parameters_for_dmin():
    """
    Poišče parametre (a, v3), za katere minimalna razdalja d_min
    približno ustreza target_dmin (+/- tol).
    
    target_dmin ... želena minimalna razdalja
    tol ........... dovoljena odstopanja
    """

    target_dmin=0.03
    tol=0.005,
    a_range=(0.414, 0.4155)
    v_range=(152, 154)
    Na=50
    Nv=100

    a_values = np.linspace(a_range[0], a_range[1], Na)
    v_values = np.linspace(v_range[0], v_range[1], Nv)

    best_matches = []

    print("\n=== Začenjam iskanje parametrov za željeni d_min ===\n")

    for a in a_values:
        for v3 in v_values:

            final, positions, velocities = run_simulation(
                a=a, q=0.5, m3=10.0, v3=v3
            )

            # najdi d_min
            (d02, t02), (d12, t12), (pair, dmin, tmin) = closest_approach(positions, dt)

            if abs(dmin - target_dmin) <= tol:
                print(f"Najdeno ujemanje: a={a:.4f}, v3={v3:.2f}, d_min={dmin:.4f}")
                best_matches.append((a, v3, dmin, pair, tmin))

    if len(best_matches) == 0:
        print("Ni najdenih začetnih pogojev v dani toleranci.")
        return None

    # vrni vse dobre pare
    return print(best_matches)


