def find_fastest_from_candidates(candidates):
    """
    candidates: list of tuples (a, v3, d_min, pair, tmin)
    Vrne kandidat z največjo končno hitrostjo izstreljene zvezde.
    """

    best_speed = -1
    best_entry = None

    print("\n=== Začenjam iskanje najhitrejše izstreljene zvezde ===\n")

    for (a, v3, dmin, pair, tmin) in candidates:
        final, positions, velocities = run_simulation(
            a=a, q=0.5, m3=10.0, v3=v3
        )

        # final = (status, pair, esc_index, v_esc)
        status, bound_pair, esc_index, v_esc = final

        print(f"a={a:.6f}, v3={v3:.6f}, d_min={dmin:.6f} → v_esc={v_esc:.4f}")

        if v_esc > best_speed:
            best_speed = v_esc
            best_entry = (a, v3, dmin, esc_index, v_esc)

    print("\n=== NAJHITREJŠI PRIMER ===")
    print(f"a={best_entry[0]:.6f}, v3={best_entry[1]:.6f}, d_min={best_entry[2]:.6f}, "
          f"esc_index={best_entry[3]}, v_esc={best_entry[4]:.4f}")

    return print(best_entry)


